       Revised Date:
    */
    static int i_Count_Vowels(String str_word) {
        final String VOWEL_LIST = "aeiou";
        int vowel_total = 0;
        // check every character of the word
        for (int i_pos = 0; i_pos < str_word.length(); i_pos++) {
            // check whether the character is a vowel
